#include <bits/stdc++.h>
using namespace std; static uint64_t mm(uint64_t a,uint64_t b,uint64_t m){return (__uint128_t)a*b%m;}static uint64_t pw(uint64_t a,uint64_t e,uint64_t m){uint64_t z=1;while(e){if(e&1)z=mm(z,a,m);a=mm(a,a,m);e>>=1;}return z;}static bool isp(uint64_t n){if(n<2)return 0;for(uint64_t p:{2ULL,3ULL,5ULL,7ULL,11ULL,13ULL,17ULL,19ULL,23ULL,29ULL,31ULL,37ULL})if(n%p==0)return n==p;uint64_t d=n-1,s=0;while(!(d&1))d>>=1,s++;for(uint64_t a:{2ULL,325ULL,9375ULL,28178ULL,450775ULL,9780504ULL,1795265022ULL}){if(a%n==0)continue;auto x=pw(a%n,d,n);if(x==1||x==n-1)continue;bool pass=0;for(int i=1;i<s;i++){x=mm(x,x,n);if(x==n-1){pass=1;break;}}if(!pass)return 0;}return 1;}static int leg(uint64_t p,int r){auto z=pw(p%r,(r-1)/2,r);return z==1?1:-1;}static vector<int>pls(int B){vector<char>c(B+1);vector<int>v;for(int i=2;i<=B;i++)if(!c[i]){v.push_back(i);if(1LL*i*i<=B)for(long long j=1LL*i*i;j<=B;j+=i)c[j]=1;}return v;}static long long eg(long long a,long long b,long long&x,long long&y){if(!b){x=1;y=0;return a;}long long X,Y,g=eg(b,a%b,X,Y);x=Y;y=X-a/b*Y;return g;}static int invm(int a,int m){long long x,y;eg(a,m,x,y);x%=m;if(x<0)x+=m;return x;}static set<int>P(int k,uint64_t a){int x=a%k;return {1,x,(int)(1LL*x*x%k)};}static set<int>mul(int k,const set<int>&A,const set<int>&B){set<int>C;for(int a:A)for(int b:B)C.insert(1LL*a*b%k);return C;}static set<int>sd(int k,int s){set<int>D={1};for(int q:{2,3,5,7})if(s%q==0)D=mul(k,D,P(k,q));return D;}
struct G{uint64_t C=0,prod=1;vector<int>rs;};
static bool test(uint64_t p,int k,G &g){int s=gcd((uint64_t)210,g.C);if(g.prod==0||g.C%(uint64_t(s)*g.prod))return 0;uint64_t m=g.C/(uint64_t(s)*g.prod);auto B=sd(k,s);for(int r:g.rs)B=mul(k,B,P(k,r));B=mul(k,B,P(k,m));int t1=(k-invm(4,k))%k,t2=(k-g.C%k)%k;return B.count(t1)||B.count(t2);}
int main(int argc,char**argv){uint64_t LIM=argc>1?strtoull(argv[1],0,10):100000000ULL;int RB=argc>2?atoi(argv[2]):1000;auto R=pls(RB);long long hard=0,sol=0,maxrank=0,worst=0;map<int,long long>hist;for(uint64_t t=0;;t++){uint64_t p=840*t+1;if(p>=LIM)break;if(!isp(p))continue;hard++;uint64_t N=(p+3)/4;map<int,G>gs;int rank=0;bool ok=0;for(int r:R){if(r<=7||leg(p,r)!=-1)continue;rank++;int j=(r-N%r)%r,k=4*j+3;uint64_t C=N+j;auto &g=gs[k];if(g.rs.empty())g.C=C; if(g.C!=C){cerr<<"bad C";return 2;}if(C%r){cerr<<"bad div";return 2;}g.rs.push_back(r);g.prod*=r;if(test(p,k,g)){ok=1;hist[rank]++;if(rank>maxrank){maxrank=rank;worst=p;}break;}}if(ok)sol++;}
cerr<<"hard="<<hard<<" solved="<<sol<<" maxrank="<<maxrank<<" worst="<<worst<<"\n";for(auto [r,n]:hist)cout<<r<<" "<<n<<"\n";}
